files.content:
:root {
  --bg: #1a1c2c;
  --card: #2a2d4a;
  --accent: #ffcd75;
  --accent-dark: #e6a800;
  --text: #f4f4f4;
  --muted: #9a9ab0;
  --danger: #e64545;
  --radius: 8px;
}

* {
  box-sizing: border-box;
}

[hidden] {
  display: none !important;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.scoreboard {
  background: var(--card);
  border-radius: var(--radius);
  padding: 24px;
  width: 100%;
  max-width: 600px;
  box-shadow: 0 8px 0 rgba(0, 0, 0, 0.4);
}

h1 {
  text-align: center;
  font-size: 1.5rem;
  margin: 0 0 24px;
  letter-spacing: 2px;
  color: var(--accent);
  text-transform: uppercase;
}

.teams {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  margin-bottom: 24px;
}

.team {
  background: rgba(0, 0, 0, 0.25);
  border-radius: var(--radius);
  padding: 16px;
  text-align: center;
}

.team-name {
  font-size: 1rem;
  margin: 0 0 8px;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 1px;
}

.score {
  font-size: 3rem;
  font-weight: 700;
  line-height: 1;
  margin-bottom: 16px;
  font-variant-numeric: tabular-nums;
  color: var(--accent);
}

.buttons {
  display: flex;
  gap: 8px;
  justify-content: center;
  flex-wrap: wrap;
}

button {
  font-family: inherit;
  font-size: 1rem;
  border: none;
  border-radius: var(--radius);
  cursor: pointer;
  padding: 10px 14px;
  background: var(--accent);
  color: #1a1c2c;
  font-weight: 700;
  transition: background 0.1s, transform 0.05s;
}

button:hover {
  background: var(--accent-dark);
}

button:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 2px;
}

button:active {
  transform: translateY(2px);
  background: var(--accent-dark);
}

.score-btn {
  min-width: 48px;
}

.controls {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 16px;
  border-top: 2px solid rgba(255, 255, 255, 0.1);
  padding-top: 16px;
}

.period {
  display: flex;
  align-items: center;
  gap: 8px;
  font-weight: 700;
}

.period-label {
  color: var(--muted);
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.period-value {
  font-size: 1.5rem;
  color: var(--accent);
  min-width: 1.5ch;
  text-align: center;
}

.period-buttons {
  display: flex;
  gap: 4px;
}

.period-buttons button {
  padding: 6px 12px;
  font-size: 1.1rem;
}

.action-btn {
  background: var(--muted);
  color: #1a1c2c;
}

.action-btn:hover {
  background: #b0b0c8;
}

.action-btn.reset {
  background: var(--danger);
  color: #fff;
}

.action-btn.reset:hover {
  background: #c03030;
}

@media (max-width: 420px) {
  .teams {
    grid-template-columns: 1fr;
  }
  .scoreboard {
    padding: 16px;
  }
  .score {
    font-size: 2.5rem;
  }
}

(function () {
  'use strict';

  var scores = [0, 0]; // index 0 = team 1, index 1 = team 2
  var period = 1;
  var history = []; // each entry: { teamIndex, points }

  var scoreEls = [
    document.getElementById('score1'),
    document.getElementById('score2')
  ];
  var periodEl = document.getElementById('period-value');
  var undoBtn = document.getElementById('undo-btn');
  var resetBtn = document.getElementById('reset-btn');
  var periodDown = document.getElementById('period-down');
  var periodUp = document.getElementById('period-up');

  function render() {
    scoreEls[0].textContent = scores[0];
    scoreEls[1].textContent = scores[1];
    periodEl.textContent = period;
    undoBtn.disabled = history.length === 0;
  }

  function addScore(teamIndex, points) {
    scores[teamIndex] += points;
    history.push({ teamIndex: teamIndex, points: points });
    render();
  }

  function undo() {
    if (history.length === 0) return;
    var last = history.pop();
    scores[last.teamIndex] -= last.points;
    render();
  }

  function resetGame() {
    scores = [0, 0];
    period = 1;
    history = [];
    render();
  }

  function changePeriod(delta) {
    var next = period + delta;
    if (next < 1 || next > 4) return;
    period = next;
    render();
  }

  // Attach score buttons
  var scoreButtons = document.querySelectorAll('.score-btn');
  for (var i = 0; i < scoreButtons.length; i++) {
    (function (btn) {
      btn.addEventListener('click', function () {
        var team = parseInt(btn.getAttribute('data-team'), 10) - 1;
        var points = parseInt(btn.getAttribute('data-points'), 10);
        addScore(team, points);
      });
    })(scoreButtons[i]);
  }

  undoBtn.addEventListener('click', undo);
  resetBtn.addEventListener('click', resetGame);
  periodDown.addEventListener('click', function () { changePeriod(-1); });
  periodUp.addEventListener('click', function () { changePeriod(1); });

  // Initial render
  render();
})();
